#include <unordered_map>
#include <vector>
#include <string>

std::vector<std::string> topologicalOrder(std::unordered_map<std::string, std::vector<std::string>> graph) {
  std::unordered_map<std::string, int> numParents;

  for (auto [node, neighbors] : graph) {
    if (numParents.count(node) == 0) {
      numParents[node] = 0;
    }

    for (std::string neighbor : neighbors) {
      numParents[neighbor] += 1;
    }
  }

  std::vector<std::string> ready;

  for (auto [node, count] : numParents) {
    if (count == 0) {
      ready.push_back(node);
    }
  }

  std::vector<std::string> order;
  while (ready.size() > 0) {
    std::string node = ready.back();
    order.push_back(node);
    ready.pop_back();

    for (std::string child : graph[node]) {
      numParents[child] -= 1;

      if (numParents[child] == 0) {
        ready.push_back(child);
      }
    }
  }

  return order;
}
```

- e = number of edges
- n = number of nodes
- Time: O(e + n)
- Space: O(n)
